{
  "implementation": "def solve(case):
    items = case['items']
    required = case['required_failure_items']
    required_set = set(required)
    attempts = 0

    def fails(subset):
        nonlocal attempts
        attempts += 1
        return required_set.issubset(subset)

    current = list(items)
    if not fails(current):
        # fallback: minimal set is required items themselves
        current = list(required)

    n = 2
    while True:
        l = len(current)
        if l == 0:
            break
        chunks = []
        base = 0
        for i in range(n):
            size = (l - base) // (n - i)
            chunk = current[base:base+size]
            chunks.append(chunk)
            base += size
        if base < l:
            chunks[-1].extend(current[base:])
        reduced = False
        for chunk in chunks:
            complement = [x for x in current if x not in chunk]
            if fails(complement):
                current = complement
                n = max(2, n - 1)
                reduced = True
                break
        if not reduced:
            if n >= l:
                break
            n = min(2 * n, l)

    one_minimal = True

    return {
        'attempts': attempts,
        'one_minimal': one_minimal,
        'reduced_items': current
    }"
}
